import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1214, own='cte_137.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)
H("888.d.1.A",3,"At a career night, Noor lists airframe mechanic, composite technician and starting her own sheet metal shop as options. She is:","identifying and comparing employment opportunities, including entrepreneurship",["naming no jobs","ignoring careers","avoiding work"],"Career paths.")
H("888.d.1.A",4,"A person who starts a small business repairing aircraft skins is acting as:","an entrepreneur",["an air traffic controller","a flight attendant","a ticket agent"],"Entrepreneur.")
H("888.d.1.B",3,"During a rivet job, Tariq holds the bucking bar steady for his partner and calls out when the rivet is set. He is demonstrating how to:","contribute and collaborate as an effective member of a team",["work alone","slow others down","avoid the task"],"Team roles.")
H("888.d.1.B",4,"Two-person riveting depends on teamwork because the:","shooter and bucker must coordinate for a good rivet",["shooter works alone","rivet sets itself","bucker can leave"],"Coordinated crew.")
H("888.d.1.C",3,"A student is told that a mechanic must never sign for a repair that was done wrong, even if a deadline is close. She is identifying:","individual ethical and legal behavior standards according to professional and industry standards",["no standards","optional rules","shop slang"],"Professional standards.")
H("888.d.1.C",4,"A mechanic's signature on a repair certifies that:","the work meets the required standards",["the work is pretty","the work is cheap","the work is fast"],"Signature meaning.")
H("888.d.1.D",3,"A class reads why mechanics must be able to read, speak and write English to follow aviation manuals and records. They are researching:","the impact of English language proficiency requirements on aviation",["no requirement","a style choice","a local custom"],"English in aviation.")
H("888.d.1.D",4,"Misreading a manual step because of a language barrier could lead to:","a repair done incorrectly",["a perfect repair","a faster repair","a free repair"],"Language risk.")
H("888.d.1.E",3,"A hangar safety talk covers lack of knowledge, complacency, pressure and fatigue as common causes of maintenance errors. They are identifying:","human factors that may impact health and safety in a workplace",["no factors","weather factors only","tool brands"],"Human factors.")
H("888.d.1.E",4,"Complacency in a hangar means a worker:","becomes too comfortable and overlooks risks",["is extra careful","is training","is on break"],"Complacency.")
H("888.d.1.F",3,"A shop requires a second mechanic to inspect control cable work, because people make mistakes. This explains:","the role of human factors in maintaining health and safety in the workplace",["no role","tool failure","paint issues"],"Human factor controls.")
H("888.d.1.F",4,"A duplicate inspection of critical work reduces the chance that:","one person's error goes unnoticed",["errors are found","safety improves","work slows to nothing"],"Duplicate inspection.")
H("888.d.1.G",3,"A mechanic refuses to sign off a repair she hasn't fully checked, even when her supervisor pushes. This shows how:","an employee's personal responsibility affects health and safety",["pressure removes responsibility","safety is optional","rules are flexible"],"Personal responsibility.")
H("888.d.1.G",4,"Taking a shortcut because 'nobody will check' shows:","poor personal responsibility",["good judgment","teamwork","extra safety"],"Own your work.")
H("888.d.1.H",3,"In a role-play, a lead asks a student to use an uncertified bolt to save time. She declines and reports it. She is applying:","reasoning skills to make ethical decisions in simulated workplace situations",["poor judgment","rule breaking","avoidance"],"Ethical reasoning.")
H("888.d.1.H",4,"Using a part that is not approved for an aircraft is:","a safety and legal violation",["acceptable","a shortcut","a bargain"],"Approved parts.")
H("888.d.1.I",3,"A shop rule says no dangling jewelry, tied-back hair and safety footwear when working around machinery. These are examples of:","industry standards related to employee appearance and health habits",["decor","optional style","random rules"],"Appearance standards.")
H("888.d.1.I",4,"Good sleep and nutrition are listed in many safety programs because they help a technician:","stay alert and avoid errors",["miss work","work slowly","ignore details"],"Health habits.")
H("888.d.1.J",3,"Dani writes a short, clear note in the logbook and then briefs the next shift in person. She is practicing:","effective written and oral communication skills",["no communication","unclear notes","mumbling"],"Written and oral.")
H("888.d.1.J",4,"A shift handoff note should include:","the work done, work remaining and any hazards",["only a name","only the date","nothing"],"Handoff content.")
H("888.d.1.K",3,"A supervisor explains a job, and the mechanic repeats the steps back to confirm them. This is an example of:","effective listening skills",["poor listening","interrupting","ignoring"],"Listening.")
H("888.d.1.K",4,"Repeating instructions back to the speaker helps ensure:","the message was understood correctly",["it is forgotten","it is ignored","it is changed"],"Read-back.")
H("888.d.1.L",3,"A mechanic learns that 'shall' in a regulation means something must be done, while 'may' means it is optional. She is applying:","FAA standard terms that have specific expectations for performance",["casual words","random terms","slang"],"FAA terms.")
H("888.d.1.L",4,"In FAA regulations, the word 'shall' indicates:","a mandatory requirement",["an optional step","a suggestion","a hint"],"Shall is mandatory.")
H("888.d.2.A",3,"Before riveting, a student puts on eye and ear protection and keeps loose clothing away from the rivet gun. She is describing:","best practices for maintenance safety, including the use of personal protective equipment",["unsafe habits","no PPE","skipping rules"],"Maintenance safety.")
H("888.d.2.A",4,"Hearing protection is worn during riveting because the noise can:","damage hearing over time",["improve hearing","cool the shop","clear the air"],"Noise hazard.")
H("888.d.2.B",3,"A student compares aluminum alloy skin, titanium fittings and steel fasteners and notes their strengths. She is identifying:","characteristics and types of metallic structures",["no metals","only plastics","only paint"],"Metal types.")
H("888.d.2.B",4,"Aluminum is widely used in aircraft skins mainly because it is:","strong for its weight",["very heavy","very brittle","very soft only"],"Light and strong.")
H("888.d.2.C",3,"A mechanic finds a dent, a crack and a corroded patch on a panel and picks matching sheet metal for the repair. She is identifying:","types of sheet metal defects and selecting repair materials",["no defects","only color","only labels"],"Defects and materials.")
H("888.d.2.C",4,"A repair patch for an aluminum skin should be made from:","material of the same type and at least the same thickness",["any scrap","thinner metal","plastic wrap"],"Match material.")
H("888.d.2.D",3,"A technician uses a dye penetrant and an eddy current probe to check a wing fitting for hidden cracks. She is explaining:","inspection and testing processes of metal structures",["painting","guessing","cleaning only"],"Inspection methods.")
H("888.d.2.D",4,"Dye penetrant testing is used to find:","surface cracks in metal parts",["internal voids only","fuel leaks","paint color"],"Penetrant testing.")
H("888.d.2.E",3,"A mechanic checks the manual to choose the rivet material, size and head type for a skin patch. She is explaining:","the selection of rivets, hardware and fasteners for a sheet metal repair",["random choice","using any bolt","skipping data"],"Fastener selection.")
H("888.d.2.E",4,"Using a rivet made of the wrong alloy can cause:","galvanic corrosion or insufficient strength",["better strength","less weight","no effect"],"Alloy matching.")
H("888.d.2.F",3,"A student lays out a patch, bends it on a brake and drills the holes at the spacing the approved data lists. She is explaining:","the layout, forming and drilling of sheet metal components per FAA-approved data",["random layout","guesswork","unapproved methods"],"Layout and forming.")
H("888.d.2.F",4,"The minimum distance from a rivet hole to the edge of a sheet is set by approved data to:","prevent tearing out at the edge",["add weight","cause cracks","reduce strength"],"Edge distance.")
H("888.d.2.G",3,"A student marks the rivet rows on a repair, sets each rivet and later drills out one that was set badly. She is explaining:","rivet layout, installation and removal per FAA-approved data",["no layout","unapproved removal","random setting"],"Rivet work.")
H("888.d.2.G",4,"To remove a faulty rivet without enlarging the hole, a mechanic should:","drill just the head and punch out the shank carefully",["pry it out","burn it","hammer the skin"],"Careful removal.")
H("888.d.3.A",3,"In shop class, Ben sets a universal head rivet, a countersunk rivet and a blind rivet, then drills one out. He is:","installing and removing solid and blind rivets",["painting rivets","bending rivets","buying rivets"],"Rivet types.")
H("888.d.3.A",4,"A countersunk rivet is chosen when the surface must be:","flush with the skin",["raised","rough","painted"],"Flush surface.")
H("888.d.3.B",3,"A student sketches a patch, labels the sheet metal thickness and shows how many rivets it needs. She is:","creating a drawing of a repair, including the number of rivets and size of sheet metal",["avoiding drawings","guessing","ignoring sizes"],"Repair drawing.")
H("888.d.3.B",4,"A repair drawing should show:","the patch size, material and rivet pattern",["only a color","only a name","a joke"],"Drawing details.")
H("888.d.3.C",3,"Using the manual's spacing rules, a student plans the rows and spacing of rivets for a skin patch. She is:","designing a rivet pattern for a specific repair",["guessing","ignoring spacing","using one rivet"],"Rivet pattern.")
H("888.d.3.C",4,"Rivets in a repair are staggered or evenly spaced so the load is:","spread across the patch",["concentrated in one spot","ignored","random"],"Load distribution.")
H("888.d.3.D",3,"A mechanic checks whether a thin skin repair can be used on a stressed wing panel or only on a light fairing. She is determining:","the applicability of sheet metal for a repair in a specific application",["no application","random choice","no limits"],"Check applicability.")
H("888.d.3.D",4,"A repair meant for a non-structural fairing may not be allowed on:","a primary structural component",["a cargo liner","a seat cover","a map light"],"Structure limits.")
H("888.d.3.E",3,"A technician opens the manufacturer's structural repair manual and builds a patch plan from its charts. She is:","designing a repair using a manufacturer's structural repair manual",["using guesses","using memory","skipping the manual"],"Use SRM.")
H("888.d.3.E",4,"A structural repair manual is the best source for:","approved repair limits and procedures for that model",["recipes","seat covers","flight plans"],"SRM authority.")
H("888.d.3.F",3,"A student sketches a damaged area, cuts a piece of aluminum to match and forms it to fit the prepared opening. She is:","sketching and building a piece of sheet metal to fit a prepared area",["buying a part","guessing","skipping a sketch"],"Fit the patch.")
H("888.d.3.F",4,"Edges of a hand-cut patch should be filed smooth to:","prevent stress cracks from starting",["add cracks","add weight","increase noise"],"Deburr.")
H("888.d.3.G",3,"A mechanic measures a dent and a crack and decides whether the panel can be patched or must be replaced. She is:","determining the extent of damage to a metallic structure and deciding if it is repairable",["ignoring damage","painting over it","guessing"],"Assess damage.")
H("888.d.3.G",4,"If damage exceeds the limits in the repair manual, the panel should be:","replaced or repaired with approved engineering data",["ignored","patched anyway","painted"],"Beyond limits.")
H("888.d.4.A",3,"Before sanding a damaged carbon fiber panel, a technician puts on a respirator and gloves because the dust irritates lungs and skin. She is describing:","best practices for maintenance safety related to composites",["no precautions","only paint tips","unsafe habits"],"Composite safety.")
H("888.d.4.A",4,"Composite dust and resin fumes are hazards, so a shop should provide:","ventilation, respiratory protection and skin protection",["no ventilation","open flames","bare hands"],"Composite hazards.")
H("888.d.4.B",3,"A mechanic taps a wood spar, checks for rot and checks glue joints with a light and a probe. She is identifying:","tools, inspection and practices for wood structures",["metal tools only","no inspection","paint only"],"Wood inspection.")
H("888.d.4.B",4,"Dark stains and soft spots in a wooden aircraft member may indicate:","decay or moisture damage",["fresh paint","new wood","good glue"],"Wood decay.")
H("888.d.4.C",3,"A restorer reads about dope, grade A cotton, Ceconite and rib stitching on a fabric-covered wing. She is researching:","terms used in textile (fabric) coverings",["engine terms","avionics terms","tire terms"],"Fabric terms.")
H("888.d.4.C",4,"Dope applied to fabric covering is used to:","tighten and seal the fabric",["loosen it","tear it","dissolve it"],"Dope purpose.")
H("888.d.4.D",3,"A restorer attaches fabric to ribs with rib lacing and uses sewn seams and reinforcing tape. She is describing:","methods of attaching textile coverings",["no methods","random methods","taping only"],"Attachment methods.")
H("888.d.4.D",4,"Rib lacing keeps fabric from:","lifting away from the ribs in flight",["staying tight","becoming stronger","getting wet"],"Rib lacing.")
H("888.d.4.E",3,"A mechanic uses a punch tester on old fabric to see if it still has strength. She is performing:","an inspection of textile coverings",["a paint job","a weight check","a tire check"],"Fabric test.")
H("888.d.4.E",4,"Fabric that fails a strength test and tears easily must be:","replaced",["ignored","painted","reused"],"Reject weak fabric.")
H("888.d.4.F",3,"A repair plan lists scarf joints, bonded patches and bolted fasteners for a cracked composite panel. She is describing:","composite repair methods and fasteners",["no repair","metal bending","paint matching"],"Repair methods.")
H("888.d.4.F",4,"A scarf repair on a composite is made by:","tapering the damaged area and bonding a matching patch",["filling with putty only","hammering","taping over it"],"Scarf joint.")
H("888.d.4.G",3,"A student sorts fiberglass, carbon fiber and aramid fibers, honeycomb cores and epoxy matrices into groups. She is identifying:","composite fiber, core and matrix materials",["metal alloys","paint types","tire rubbers"],"Composite materials.")
H("888.d.4.G",4,"In a composite, the matrix (such as epoxy) serves to:","bind the fibers and transfer loads between them",["replace the fibers","cool the part","fuel the part"],"Matrix role.")
H("888.d.4.H",3,"A technician finds a spot where plies have separated and a dent where the honeycomb core is crushed. She is identifying:","common composite defects such as delamination and crushed core",["no defects","paint chips","loose cables"],"Composite defects.")
H("888.d.4.H",4,"Delamination is when:","layers of the composite separate from each other",["layers fuse together","paint peels","fabric tears"],"Delamination.")
H("888.d.4.I",3,"A mechanic taps along a composite skin with a coin and listens for a dull sound, then uses an ultrasonic unit. She is performing:","inspection and testing of composites",["no inspection","a paint job","a tire check"],"Composite NDT.")
H("888.d.4.I",4,"A dull sound during a tap test usually indicates:","a possible void or delamination",["a perfect bond","an overweight part","new paint"],"Dull means defect.")
H("888.d.4.J",3,"A mechanic cleans a plexiglass side window with mild soap and a soft cloth, never a harsh solvent. She is describing:","window care and maintenance",["window removal","harsh scrubbing","no care"],"Window care.")
H("888.d.4.J",4,"A dry, abrasive cloth can harm an acrylic window because it can:","scratch the surface",["strengthen it","clean it deeply","heal cracks"],"Scratches.")
H("888.d.4.K",3,"A technician learns that acrylic and polycarbonate are thermoplastics and checks them for crazing and cracks. She is covering:","inspection and types of thermoplastics",["metal only","fabric only","wood only"],"Thermoplastics.")
H("888.d.4.K",4,"Crazing in an acrylic window appears as:","a network of fine cracks",["a clear surface","a bright coating","a smooth finish"],"Crazing.")
H("888.d.4.L",3,"A mechanic uses a clear patch to stop a small crack as a temporary fix until a new window is installed. She is describing:","temporary and permanent repairs to windows",["no repairs","paint only","wax only"],"Window repairs.")
H("888.d.4.L",4,"A crack in a pressurized cabin window usually requires:","replacement rather than a simple patch",["tape forever","paint","nothing"],"Pressurized windows.")
H("888.d.4.M",3,"A mechanic checks seat belts for fraying, buckle function and worn upholstery before release. She is performing:","an inspection of restraints and upholstery",["no inspection","painting","engine work"],"Restraint check.")
H("888.d.4.M",4,"A frayed seat belt should be:","removed from service and replaced",["ignored","taped","used anyway"],"Replace frayed belts.")
H("888.d.5.A",3,"A technician checks a fiberglass wingtip, a plastic fairing and a laminated windshield for damage and plans repairs. She is:","inspecting and repairing fiberglass, composite, plastic and glass-laminated components",["avoiding repair","painting only","buying parts"],"Inspect and repair.")
H("888.d.5.A",4,"Repair of laminated glass components must follow:","manufacturer-approved procedures",["guesswork","any glue","rumors"],"Approved procedures.")
H("888.d.5.B",3,"A student cleans an acrylic windshield with water and soft cloth, then checks for crazing and scratches. She is:","cleaning and inspecting acrylic windshields",["scrubbing with solvent","skipping inspection","painting it"],"Windshield care.")
H("888.d.5.B",4,"Acrylic windshields should not be cleaned with:","strong solvents such as acetone",["mild soap","clean water","a soft cloth"],"Avoid solvents.")
H("888.d.5.C",3,"A mechanic taps a composite panel with a coin and listens for changes in the sound. She is performing:","a tap test on a composite",["a pressure test","a leak test","a fuel test"],"Tap test.")
H("888.d.5.C",4,"A tap test is most useful for finding:","bond line problems such as delaminations",["fuel leaks","engine noise","tire wear"],"Tap test use.")
H("888.d.5.D",3,"A bolt hole in a composite has become oval from wear, and the manual describes how to repair it. She is following:","repair procedures for elongated bolt holes",["no procedure","a guess","a shortcut"],"Elongated holes.")
H("888.d.5.D",4,"An elongated bolt hole in a structure is a problem because it:","lets the fastener move and weaken the joint",["adds strength","improves fit","reduces wear"],"Slop in joint.")
H("888.d.5.E",3,"A student lays plies in a mold and places the bagging film and bleeder before applying vacuum. She is:","performing a composite lay-up, including preparation for vacuum bagging",["painting a part","cutting metal","welding steel"],"Lay-up and bagging.")
H("888.d.5.E",4,"The vacuum in bagging helps by:","compressing the plies and removing air and extra resin",["adding air","adding heat only","loosening plies"],"Vacuum role.")
H("888.d.6.A",3,"A mechanic checks a flight control cable for broken wires, rust and kinks during an inspection. She is describing:","types of control cables and their maintenance",["no maintenance","paint only","tire care"],"Cable care.")
H("888.d.6.A",4,"Broken strands in a control cable should be:","counted against the manual's limits and replaced if exceeded",["ignored","taped","painted"],"Cable limits.")
H("888.d.6.B",3,"A mechanic checks the turnbuckles, pulleys, fairleads and travel stops on a cable run. She is inspecting:","cable connectors, guides and stops",["engines","tires","paint"],"Cable hardware.")
H("888.d.6.B",4,"A fairlead is used to:","guide a cable and keep it from rubbing",["pull the cable","cut the cable","paint the cable"],"Fairlead.")
H("888.d.6.C",3,"A mechanic checks a push-pull tube and a torque tube for corrosion and bent ends. She is inspecting:","push-pull tubes and torque tubes",["cables only","pulleys only","tires only"],"Push-pull tubes.")
H("888.d.6.C",4,"A push-pull tube transmits motion by:","pushing and pulling along its length",["twisting only","stretching","burning"],"Push-pull.")
H("888.d.6.D",3,"A mechanic checks a bellcrank pivot for play and smooth movement. She is inspecting:","bellcranks in a control system",["tires","wings only","paint"],"Bellcrank.")
H("888.d.6.D",4,"A bellcrank is used to:","change the direction of motion in a control linkage",["add fuel","hold paint","spin a prop"],"Bellcrank use.")
H("888.d.6.E",3,"A shop schedules its cable tension meters for periodic calibration so the readings stay accurate. She is describing:","the calibration schedule for cable tension meters",["no schedule","random schedule","once a decade"],"Calibration.")
H("888.d.6.E",4,"An uncalibrated tension meter could cause:","wrong cable tension settings",["perfect tension","no settings","less cable"],"Bad readings.")
H("888.d.6.F",3,"A mechanic wraps a tensiometer around a cable, reads the dial and looks up the right tension on the chart for the cable size. She is:","using a cable tensiometer and tension chart",["guessing","skipping a chart","using a ruler"],"Tensiometer.")
H("888.d.6.F",4,"Cable tension charts account for the cable size and:","the temperature at the time of the check",["the paint color","the pilot's weight","the seat type"],"Temperature correction.")
H("888.d.6.G",3,"A technician learns that a control surface that is out of balance can start to flutter in flight. She is describing:","flutter and balance of flight controls",["no flutter","tire balance","engine balance"],"Flutter.")
H("888.d.6.G",4,"Adding paint or repair material to a control surface can:","upset its balance and increase flutter risk",["improve balance always","lower weight","do nothing"],"Rebalance after repair.")
H("888.d.6.H",3,"A student names the ailerons, elevator and rudder as primary controls, and the stabilizers as fixed or adjustable surfaces. She is identifying:","primary flight controls and stabilizers",["secondary controls only","engines","tires"],"Primary controls.")
H("888.d.6.H",4,"The primary flight controls move the aircraft about its:","pitch, roll and yaw axes",["fuel axes","engine axes","tire axes"],"Three axes.")
H("888.d.6.I",3,"A student lists flaps, slats, spoilers and trim tabs as controls that help with lift, drag or balance. She is identifying:","secondary or auxiliary control surfaces",["primary controls","engines","tires"],"Secondary controls.")
H("888.d.6.I",4,"Flaps are lowered during landing to:","increase lift at lower speeds",["increase speed","reduce lift","stop engines"],"Flaps.")
H("888.d.7.A",3,"A mechanic uses the manual to find turnbuckles and stops that can be adjusted when rigging. She is locating:","rigging adjustment points",["no points","paint spots","engine parts"],"Rigging points.")
H("888.d.7.A",4,"Turnbuckles are used to:","adjust cable length and tension",["cut cables","paint cables","hold fuel"],"Turnbuckle use.")
H("888.d.7.B",3,"A mechanic moves a rudder through its range and checks for binding, freeplay and correct direction. She is:","inspecting primary and secondary control surfaces",["not inspecting","painting","fueling"],"Control inspection.")
H("888.d.7.B",4,"A control surface that binds should be:","investigated and corrected before flight",["flown anyway","painted","ignored"],"Fix binding.")
H("888.d.7.C",3,"A mechanic runs her gloved hand along a primary control cable and feels for snags. She is:","inspecting primary control cables",["ignoring cables","painting cables","buying cables"],"Cable feel test.")
H("888.d.7.C",4,"A snag felt on a cable usually means:","a broken wire strand",["perfect cable","extra grease","a good splice"],"Snag means broken wire.")
H("888.d.7.D",3,"After setting tension, a mechanic safeties the turnbuckle with wire so it cannot loosen. She is:","adjusting and securing a primary control cable",["leaving it loose","skipping safeties","removing it"],"Safety the turnbuckle.")
H("888.d.7.D",4,"A properly safetied turnbuckle should show:","no more than three threads exposed at each end",["all threads exposed","no threads engaged","a gap at one end"],"Thread engagement.")
H("888.d.7.E",3,"A mechanic adjusts the end fittings of a push-pull rod to set the control travel. She is:","adjusting push-pull systems",["adjusting cables only","painting rods","cutting rods"],"Push-pull adjusting.")
H("888.d.7.E",4,"Rod end fittings must have enough thread engagement, shown by:","a check hole or inspection mark",["a paint dot","a sticker","a scratch"],"Check hole.")
H("888.d.7.F",3,"After a repaint, a mechanic puts the aileron on a balancing stand to see if it stays level. She is:","balancing a control surface",["painting it","weighing fuel","testing a tire"],"Static balance.")
H("888.d.7.F",4,"A control surface that is nose heavy or tail heavy after repair must be:","rebalanced per the manual",["flown as is","painted again","left alone"],"Rebalance.")
H("888.d.7.G",3,"A mechanic shakes a control surface bearing and compares the play to the manual's axial play limit. She is checking:","the limits for axial play of a control bearing",["tire pressure","paint thickness","fuel level"],"Axial play.")
H("888.d.7.G",4,"Bearing play beyond limits can lead to:","control flutter or wear",["better control","less noise","no effect"],"Excess play.")
H("888.d.7.H",3,"A mechanic looks up the control surface travel limits in the type certificate data sheet or manual. She is:","locating data for control travel limits",["guessing travel","ignoring limits","painting surfaces"],"Travel limits.")
H("888.d.7.H",4,"Control travel must be set to the specified degrees so the aircraft:","has correct control authority and doesn't overstress",["has less lift","flies faster","burns more fuel"],"Correct travel.")
H("888.d.8.A",3,"A mechanic reads the section of Part 43 that lists what must be inspected for an annual and a 100-hour inspection. She is identifying:","inspection requirements under 14 CFR Part 43",["no requirements","optional steps","shop rumors"],"Part 43 inspections.")
H("888.d.8.A",4,"The scope and detail of an annual inspection are set out in:","the appendix to Part 43",["a sales flyer","a seat manual","a paint chart"],"Part 43 appendix.")
H("888.d.8.B",3,"After a repair, the mechanic writes down the work done, the date and her certificate number as Part 43 requires. She is meeting:","maintenance recordkeeping requirements",["no records","optional notes","shop gossip"],"Records required.")
H("888.d.8.B",4,"A Part 43 maintenance entry must include a description of the work and the:","date the work was completed",["weather forecast","pilot's lunch","hangar temperature"],"Entry contents.")
H("888.d.8.C",3,"A mechanic finds an AD that applies to the propeller hub on her shop's airplane and checks how often it must be done. She is applying:","airworthiness directives",["sales brochures","optional tips","shop rules"],"AD compliance.")
H("888.d.8.C",4,"An airworthiness directive is:","a mandatory FAA rule to fix an unsafe condition",["a suggestion","a sales offer","an old rumor"],"AD mandatory.")
H("888.d.8.D",3,"A mechanic compares the approved manufacturer repair manual with an unapproved internet forum post and uses the manual. She is explaining:","the difference between FAA-approved data and other data sources",["no difference","a style choice","a guess"],"Approved data.")
H("888.d.8.D",4,"A forum post describing a repair method can be used as the basis for a repair only if:","it is approved or acceptable data",["it is popular","it is short","it is new"],"Acceptable data.")
H("888.d.8.E",3,"A mechanic reads a manufacturer service letter about an optional improvement and a bulletin about a recommended inspection. She is learning about:","service letters and service bulletins",["tire ads","fuel charts","paint ads"],"Service docs.")
H("888.d.8.E",4,"A manufacturer's service bulletin is normally:","advisory unless made mandatory by an AD",["always mandatory","unrelated to aircraft","legally binding on pilots"],"SB vs AD.")
H("888.d.8.F",3,"A mechanic walks around the aircraft looking for cracks, leaks, loose fasteners and corrosion. She is explaining:","the purpose and methods of visual inspections",["no inspection","a paint check","a sales pitch"],"Visual inspection.")
H("888.d.8.F",4,"A good visual inspection uses good lighting, a mirror and a flashlight to see:","hard-to-reach areas where defects can hide",["only the paint","only the tires","nothing at all"],"Inspection aids.")
